// Records what the real jq does for a list of programs, so that src/jq.ts can
// be checked against it without jq being installed.
//
//   node test/fixtures/jq-cases.gen.mjs     (needs jq 1.7 on PATH; not run in CI)
//
// writes test/fixtures/jq-cases.json: for each case { program, input, vars? }
// either `outputs` (jq -c, one parsed value per line) or `error: true`.
//
// Left out on purpose, because Encela's jq differs there (see src/jq.ts):
// objects with integer-like keys where key order shows, the text of number
// literals (jq keeps `1.0` and `1e3` as written), numbers past 2^53, error
// messages, `$ENV`/`env`, `$__loc__.file`, `now`, and the builtins this jq
// does not have (trim, ltrim, rtrim, leaf_paths, ascii, date).
import { spawnSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

